using System;

namespace HitMe.NetClientV1
{
    /// <summary>Validates the six-character room codes generated by RoomDirectory.</summary>
    public static class RoomCode
    {
        // Keep in sync with server/Authority/RoomAuthority.cs:RoomDirectory.CodeAlphabet.
        public const string Alphabet = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
        public const int Length = 6;

        public static bool TryNormalize(string raw, out string code)
        {
            code = string.IsNullOrWhiteSpace(raw) ? string.Empty : raw.Trim().ToUpperInvariant();
            if (code.Length != Length) return false;
            for (int i = 0; i < code.Length; i++)
                if (Alphabet.IndexOf(code[i]) < 0) return false;
            return true;
        }
    }
}
